const docCount = $input.all().length;
return [{
  json: {
    status: 'success',
    chunks_stored: docCount,
    message: `Multimodel ingest ${docCount} chunks stored.`
  }
}];

const input = $input.first().json;

const body = input.body || input;
const question = (body.question || '').trim();

if (!question) {
  throw new Error('Missing field: send {"question": "your query here"} in the POST body');
}

return [
  {
    json: {
      question: question,
      received_at: new Date().toISOString()
    }
  }
];

// Safely extract answer from current input
const inputFirst = $input.first();
const answer = inputFirst?.json?.response || "";

// Safely retrieve question from target node without blowing up if missing
let question = "Unknown Question";
try {
  question = $node["Code - Parse & Validate Question"].json.question;
} catch (e) {
  // Falls back gracefully if node hasn't run or doesn't exist
  question = "Question node not found or not executed";
}

// Detect "not found" signals
const notFoundPhrases = [
  "i don't know", "i do not know", "i cannot find",
  "not found in", "no information", "not mentioned",
  "i have no", "unable to find", "doesn't contain"
];

const answerLower = answer.toLowerCase();

const notFound = !answer || 
  notFoundPhrases.some(p => answerLower.includes(p)) ||
  answer.startsWith('❌');

const partial = answer.startsWith('⚠️');

// Citation & Quality Checks
const hasCite = answer.includes('📄 Source:') || 
  answer.includes('Source:') || 
  /source:/i.test(answer);

const wordCount = answer.trim() ? answer.split(/\s+/).length : 0;

const debugFlags = [];

if (!hasCite && !notFound) {
  debugFlags.push('missing_source');
}

if (wordCount < 10 && !notFound) {
  debugFlags.push('very_short_answer');
}

// Check for contradictory status (has fallback text but not marked notFound)
if (notFoundPhrases.some(p => answerLower.includes(p)) && !notFound) {
  debugFlags.push('hallucinated_fallback');
}

const httpStatus = notFound ? 404 : 200;

return [{
  json: {
    question,
    answer: notFound ? '❌ No relevant information found in the knowledge base for your query.' : answer,
    status: notFound ? 'not_found' : (partial ? 'partial' : 'ok'),
    has_citation: hasCite,
    http_status: httpStatus,
    debug: debugFlags.length > 0 ? debugFlags : undefined,
    answered_at: new Date().toISOString()
  }
}];

const b = $input.first().binary;

if (!b) {
  throw new Error('Upload a file as multipart binary (field "data").');
}

const k = Object.keys(b)[0];
const bin = b[k];

const mime = (
  bin.mimeType || 'application/octet-stream'
)
  .toLowerCase()
  .split(';')[0]
  .trim();

const GEMINI_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/gif',
  'image/webp',
  'image/heic',
  'image/heif',

  'application/pdf',

  'audio/wav',
  'audio/mp3',
  'audio/mpeg',
  'audio/aiff',
  'audio/aac',
  'audio/ogg',
  'audio/flac',

  'video/mp4',
  'video/mpeg',
  'video/quicktime',
  'video/x-msvideo',
  'video/x-flv',
  'video/webm',
  'video/x-ms-wmv',
  'video/3gpp'
]);

const DIRECT_TYPES = new Set([
  'text/plain',
  'text/markdown',
  'text/x-markdown',
  'text/csv',
  'text/html',
  'text/xml',
  'application/json',
  'application/xml'
]);

const UNSUPPORTED = {
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
    'DOCX detected - convert to PDF and re-upload.',

  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':
    'XLSX detected - export as CSV and re-upload.',

  'application/msword':
    'DOC detected - convert to PDF and re-upload.',

  'application/vnd.ms-excel':
    'XLS detected - export as CSV and re-upload.'
};

if (UNSUPPORTED[mime]) {
  throw new Error(UNSUPPORTED[mime]);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, k);


// ======================================================
// DIRECT TEXT FILES
// ======================================================

if (DIRECT_TYPES.has(mime)) {

  const text = buffer.toString('utf8');

  return [
    {
      json: {
        _meta: {
          route: 'direct',
          directText: text
        }
      }
    }
  ];
}


// ======================================================
// CHECK GEMINI SUPPORTED TYPES
// ======================================================

if (!GEMINI_TYPES.has(mime)) {
  throw new Error(`Unsupported file type: "${mime}".`);
}


// ======================================================
// CONVERT FILE TO BASE64
// ======================================================

const b64 = buffer.toString('base64');


// ======================================================
// CREATE PROMPT
// ======================================================

let promptText;

if (mime.startsWith('image/')) {

  promptText =
    'Describe the image in detail and transcribe all visible text. Output plain text only.';

} else if (mime === 'application/pdf') {

  promptText =
    'Extract and transcribe all text from this PDF. Preserve structure where possible. Output plain text only.';

} else if (mime.startsWith('audio/')) {

  promptText =
    'Transcribe all spoken content. Include speaker labels where distinguishable. Output plain text only.';

} else if (mime.startsWith('video/')) {

  promptText =
    'Describe the video content and transcribe all visible text and spoken dialogue. Output plain text only.';

}


// ======================================================
// GEMINI GENERATECONTENT REQUEST
// ======================================================

return [
  {
    json: {
      _meta: {
        route: 'gemini'
      },

      requestBody: {
        contents: [
          {
            parts: [
              {
                text: promptText
              },
              {
                inline_data: {
                  mime_type: mime,
                  data: b64
                }
              }
            ]
          }
        ]
      }
    }
  }
];

const meta = $json._meta || {};
const text = meta.directText || '';

if (!text.trim()) throw new Error('No text content found in the uploaded file.');

const buf = Buffer.from(text, 'utf8');

return {
  json: {
    source: 'direct_extract',
    model: 'none',
    originalFileName: meta.originalFileName || 'file',
    originalMimeType: meta.originalMimeType || 'text/plain',
    ingestedAt: new Date().toISOString()
  },
  binary: {
    data: {
      data: buf.toString('base64'),
      mimeType: 'text/plain',
      fileName: 'extracted.txt'
    }
  }
};

// ======================================================
// GEMINI RESPONSE -> TEXT FILE
// ======================================================

// Get the JSON response from Gemini
const response = $input.first().json;


// ======================================================
// FIND GENERATED TEXT
// ======================================================

let text = '';


// Standard Gemini generateContent response
if (
  response.candidates &&
  response.candidates[0] &&
  response.candidates[0].content &&
  response.candidates[0].content.parts
) {
  text = response.candidates[0].content.parts
    .map(part => part.text || '')
    .join('\n');
}


// ======================================================
// CHECK RESULT
// ======================================================

if (!text.trim()) {
  throw new Error(
    'Gemini returned no text. Full response: ' +
    JSON.stringify(response)
  );
}


// ======================================================
// CONVERT TEXT TO BINARY
// ======================================================

const buffer = Buffer.from(text, 'utf8');


// ======================================================
// RETURN BINARY FILE
// ======================================================

return [
  {
    json: {
      fileName: 'gemini-output.txt',
      mimeType: 'text/plain',
      textLength: text.length
    },

    binary: {
      data: await this.helpers.prepareBinaryData(
        buffer,
        'gemini-output.txt',
        'text/plain'
      )
    }
  }
];
